CREATE OR REPLACE FUNCTION nexus.plain_search_384( p_query nexus.vector(384), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
