CREATE OR REPLACE FUNCTION nexus.hybrid_search_384( p_query nexus.vector(384), p_query_text text, p_collections text[], p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, score float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH gate AS ( SELECT encode(c.chash, 'hex') AS id, c.chunk_text, c.collection, row_number() OVER (ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, c.chash ASC) AS vec_rank, row_number() OVER (ORDER BY ts_rank_cd(c.chunk_tsv, plainto_tsquery('english', p_query_text)) DESC, c.chash ASC) AS ts_rank, row_number() OVER (ORDER BY nexus.word_similarity(p_query_text, c.chunk_text) DESC, c.chash ASC) AS trgm_rank FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ) SELECT g.id, g.chunk_text, g.collection, (1.0 / (60 + g.vec_rank) + 1.0 / (60 + g.ts_rank) + 1.0 / (60 + g.trgm_rank))::float8 AS score FROM gate g ORDER BY score DESC, g.id ASC LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.hybrid_search_768( p_query nexus.vector(768), p_query_text text, p_collections text[], p_where jsonb, p_n int ) RETURNS TABLE(id text, content text, collection text, score float8) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH gate AS ( SELECT encode(c.chash, 'hex') AS id, c.chunk_text, c.collection, row_number() OVER (ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, c.chash ASC) AS vec_rank, row_number() OVER (ORDER BY ts_rank_cd(c.chunk_tsv, plainto_tsquery('english', p_query_text)) DESC, c.chash ASC) AS ts_rank, row_number() OVER (ORDER BY nexus.word_similarity(p_query_text, c.chunk_text) DESC, c.chash ASC) AS trgm_rank FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (p_where IS NULL OR c.metadata @> p_where) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ) SELECT g.id, g.chunk_text, g.collection, (1.0 / (60 + g.vec_rank) + 1.0 / (60 + g.ts_rank) + 1.0 / (60 + g.trgm_rank))::float8 AS score FROM gate g ORDER BY score DESC, g.id ASC LIMIT p_n $$;
