CREATE OR REPLACE FUNCTION nexus.search_topic_scoped_384( p_query nexus.vector(384), p_topic_label text, p_collection text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.retention FROM nexus.chunks c JOIN nexus.topic_assignments ta ON ta.tenant_id = c.tenant_id AND ta.doc_id = c.chash JOIN nexus.topics t ON t.tenant_id = ta.tenant_id AND t.id = ta.topic_id WHERE c.collection = p_collection AND t.collection = p_collection AND t.label = p_topic_label AND c.embedding_384 IS NOT NULL AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
